// Load the redesign job (kind='redesign', source_type='llm_redesign') + its seed canvas
const gatewayUrl = $env.AISHA_GATEWAY_URL;
const serviceKey = $env.AISHA_SERVICE_KEY;
const body = $input.first().json.body ?? $input.first().json;
const job_id = body.job_id;
if (!job_id) throw new Error('job_id required');

const res = await fetch(`${gatewayUrl}/rest/v1/web_artifact_jobs?id=eq.${job_id}&select=id,story_id,seed_canvas_data,brief,slot_profile,creativity_seed,metadata,status`, {
  headers: {
    'apikey': serviceKey,
    'authorization': `Bearer ${serviceKey}`,
    'accept': 'application/json'
  }
});
if (!res.ok) throw new Error(`load job ${res.status}`);
const rows = await res.json();
if (!rows.length) throw new Error('job not found');
const job = rows[0];

if (!['pending', 'processing'].includes(job.status)) {
  throw new Error(`job in unexpected status: ${job.status}`);
}

return [{ json: { ...job, llm_mock: ($env.AISHA_LLM_MOCK === '1' || $env.AISHA_LLM_MOCK === 'true') } }];

// Mark processing via RPC
const gatewayUrl = $env.AISHA_GATEWAY_URL;
const serviceKey = $env.AISHA_SERVICE_KEY;
const { id: job_id, status } = $input.first().json;

if (status === 'pending') {
  const res = await fetch(`${gatewayUrl}/rest/v1/rpc/mark_web_artifact_processing`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'apikey': serviceKey,
      'authorization': `Bearer ${serviceKey}`
    },
    body: JSON.stringify({ p_job_id: job_id })
  });
  if (!res.ok) {
    const t = await res.text();
    throw new Error(`mark_processing failed: ${res.status} ${t}`);
  }
}
return $input.all();

// Real LLM redesign through the Aisha router.
//
// Calls /functions/v1/ai-generate with task_kind='occipitum_redesign'.
// The workflow does NOT pick a model — svc-ai-chat delegates to
// route_task RPC (dirigent decision tree + agent_catalog), which
// picks the agent + model based on platform-level config.
// Operator-side constraints (brief, prior_style_bands, slot_hint)
// are passed as advisory `constraints`; Aisha may or may not honor.
//
// AISHA_LLM_MOCK is honored server-side. After the LLM returns
// ProjectData JSON, we enforce HARD GATE invariants:
//   - every data-runtime-block placeholder preserved verbatim
//   - every data-i18n-key preserved
// On failure: fail_web_artifact_ingest RPC writes a web_artifact_failed
// story_entry with reason.

const gatewayUrl = $env.AISHA_GATEWAY_URL;
const serviceKey = $env.AISHA_SERVICE_KEY;
const job = $input.first().json;
const seed = job.seed_canvas_data ?? {};
const seedHtml = seed.pages?.[0]?.component ?? '';
const brief = job.brief ?? 'Restyle this canvas while preserving every content text and every data-runtime-block placeholder verbatim.';

function extractPlaceholders(html) {
  const matches = Array.from(html.matchAll(/<[^>]*data-runtime-block="([^"]+)"[^>]*data-block-config='([^']*)'[^>]*>/g));
  return matches.map((m) => ({ blockType: m[1], config: m[2] }));
}

function extractI18nKeys(html) {
  const matches = Array.from(html.matchAll(/data-i18n-key="([^"]+)"/g));
  return Array.from(new Set(matches.map((m) => m[1]))).sort();
}

const seedPlaceholders = extractPlaceholders(seedHtml);
const seedI18n = extractI18nKeys(seedHtml);

const systemPrompt = `You are OCCIPITUM — AISHA's visual cortex.\n\nMission: redesign the GIVEN canvas while preserving:\n  1. Every <... data-runtime-block="..." ...> placeholder verbatim (count + types + data-block-config JSON identical)\n  2. Every data-i18n-key attribute and its position\n  3. Every visible text node (case-insensitive whitespace-normalised match)\n\nYou MAY:\n  - restyle wrapper elements (typography, spacing, colors)\n  - rearrange decorative layout\n  - add tasteful animations through CSS classes (no inline JS)\n\nYou MUST NOT:\n  - drop, rename, or duplicate any data-runtime-block placeholder\n  - alter visible content text\n  - emit any <script> or on*= attributes\n\nOPERATOR BRIEF: ${brief}\n\nOUTPUT FORMAT (return ONLY this JSON, no markdown fences):\n{\n  "pages": [{ "component": "<body>...preserved+restyled HTML...</body>" }],\n  "styles": [],\n  "_occipitum_rationale": {\n    "style_band": "<one of: experimental_brutalist | editorial_storytelling | luxury_immersive>",\n    "preservation_checklist": {\n      "runtime_blocks_preserved": <number>,\n      "i18n_keys_preserved": <number>,\n      "content_texts_preserved": <number>\n    }\n  }\n}`;

const userPrompt = `Seed canvas HTML:\n${seedHtml}\n\nPlaceholders to preserve: ${seedPlaceholders.length}\ni18n keys to preserve: ${seedI18n.length}`;

const genRes = await fetch(`${gatewayUrl}/functions/v1/ai-generate`, {
  method: 'POST',
  headers: { 'content-type': 'application/json', 'authorization': `Bearer ${serviceKey}` },
  body: JSON.stringify({
    task_kind: 'occipitum_redesign',
    risk_profile: 'low',
    story_id: job.story_id,
    domain: ['web', 'design'],
    constraints: {
      brief,
      slot_hint: job.slot_profile ?? null,
      prior_style_bands: job.metadata?.style_band_history ?? [],
      runtime_blocks_to_preserve: seedPlaceholders.length,
      i18n_keys_to_preserve: seedI18n.length
    },
    system: systemPrompt,
    messages: [{ role: 'user', content: userPrompt }],
    max_tokens: 8000,
    json_mode: true,
    metadata: { job_id: job.id, story_id: job.story_id }
  })
});

if (!genRes.ok) {
  const detail = await genRes.text();
  await fetch(`${gatewayUrl}/rest/v1/rpc/fail_web_artifact_ingest`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'apikey': serviceKey, 'authorization': `Bearer ${serviceKey}` },
    body: JSON.stringify({ p_job_id: job.id, p_error_message: `ai_generate_failed: ${genRes.status} ${detail}` })
  });
  throw new Error(`/ai-generate ${genRes.status}: ${detail}`);
}

const genBody = await genRes.json();
let projectData;
try {
  projectData = JSON.parse(genBody.text);
} catch (parseErr) {
  await fetch(`${gatewayUrl}/rest/v1/rpc/fail_web_artifact_ingest`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'apikey': serviceKey, 'authorization': `Bearer ${serviceKey}` },
    body: JSON.stringify({ p_job_id: job.id, p_error_message: `ai_generate_invalid_json: ${parseErr.message}` })
  });
  throw new Error('AI generate returned non-JSON output');
}

const proposedHtml = projectData.pages?.[0]?.component ?? '';
const styleBand = projectData._occipitum_rationale?.style_band ?? 'editorial_storytelling';

const outPlaceholders = extractPlaceholders(proposedHtml);
const outI18n = extractI18nKeys(proposedHtml);
const missingPlaceholders = seedPlaceholders.filter((p) => !outPlaceholders.find((o) => o.blockType === p.blockType));
const missingI18n = seedI18n.filter((k) => !outI18n.includes(k));

if (missingPlaceholders.length || missingI18n.length) {
  await fetch(`${gatewayUrl}/rest/v1/rpc/fail_web_artifact_ingest`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'apikey': serviceKey, 'authorization': `Bearer ${serviceKey}` },
    body: JSON.stringify({
      p_job_id: job.id,
      p_error_message: `runtime_block_invariant_violated: dropped=${missingPlaceholders.map((p) => p.blockType).join(',')}; missing_i18n=${missingI18n.join(',')}`
    })
  });
  throw new Error('Verify gate rejected redesign (invariant violation).');
}

const proposedCanvas = {
  ...seed,
  ...projectData,
  pages: [{ ...(seed.pages?.[0] ?? {}), ...projectData.pages?.[0], component: proposedHtml }]
};

return [{ json: { job_id: job.id, story_id: job.story_id, proposedCanvas, proposedHtml, styleBand, mockMode: !!genBody.mock, provider: genBody.provider, model: genBody.model, run_id: genBody.run_id, agent_slug: genBody.agent_slug, usage: genBody.usage } }];

// Persist proposed canvas via complete_web_artifact_ingest RPC
const gatewayUrl = $env.AISHA_GATEWAY_URL;
const serviceKey = $env.AISHA_SERVICE_KEY;
const { job_id, proposedCanvas, proposedHtml, styleBand, mockMode } = $input.first().json;

const res = await fetch(`${gatewayUrl}/rest/v1/rpc/complete_web_artifact_ingest`, {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'apikey': serviceKey,
    'authorization': `Bearer ${serviceKey}`
  },
  body: JSON.stringify({
    p_job_id: job_id,
    p_canvas_data: proposedCanvas,
    p_canvas_html: proposedHtml,
    p_canvas_css: '',
    p_extracted_tokens: null,
    p_metadata: { style_band: styleBand, mock_mode: mockMode }
  })
});

if (!res.ok) {
  const t = await res.text();
  throw new Error(`complete failed: ${res.status} ${t}`);
}

await fetch(`${gatewayUrl}/rest/v1/rpc/log_integration_action`, {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'apikey': serviceKey,
    'authorization': `Bearer ${serviceKey}`
  },
  body: JSON.stringify({
    p_integration: 'n8n',
    p_action_key: 'web_artifact.redesign.complete',
    p_payload: { job_id, style_band: styleBand, mock_mode: mockMode },
    p_tags: ['stack', 'story', 'web_artifact', 'redesign', 'complete']
  })
});

return [{ json: { job_id, status: 'ready_for_review' } }];
